<script setup>defineProps({variant:{default:'text'},width:{default:'100%'},height:[String,Number],lines:{default:3},radius:String})</script><template><div v-if="variant==='text'" class="sk-lines" :style="{width}"><i v-for="n in lines" :key="n" :style="{height:height||'14px',width:n===lines?'62%':'100%',borderRadius:radius}"/></div><i v-else class="sk" :class="`sk--${variant}`" :style="{width,height:height||variant==='card'?'96px':'44px',borderRadius:radius}"/></template><style scoped>.sk-lines{display:flex;flex-direction:column;gap:10px}.sk,.sk-lines i{display:block;background:linear-gradient(90deg,var(--progress-none) 25%,color-mix(in srgb,var(--text-primary) 8%,transparent) 37%,var(--progress-none) 63%);background-size:200% 100%}.sk-lines i{border-radius:var(--radius-xs)}.sk--card{border-radius:var(--radius-lg)}.sk--circle{border-radius:50%}@media(prefers-reduced-motion:no-preference){.sk,.sk-lines i{animation:aurora-shimmer 1.6s infinite}}</style>
